var S=state;if(typeof S.y==='undefined')S.y=155;if(typeof S.v==='undefined')S.v=0;if(typeof S.pipe==='undefined')S.pipe=410;if(typeof S.gap==='undefined')S.gap=150;if(typeof S.score==='undefined')S.score=0;S.over=!!S.over;function draw(){var top=Math.max(0,S.gap-55),bottom=Math.min(270,S.gap+55),h='';h+='<rect x='+S.pipe+' y=0 width=52 height='+top+' fill=#62c44a stroke=#263a27 stroke-width=3></rect>';h+='<rect x='+(S.pipe-4)+' y='+(top-14)+' width=60 height=18 rx=4 fill=#76d75a stroke=#263a27 stroke-width=3></rect>';h+='<rect x='+S.pipe+' y='+bottom+' width=52 height='+(270-bottom)+' fill=#62c44a stroke=#263a27 stroke-width=3></rect>';h+='<rect x='+(S.pipe-4)+' y='+bottom+' width=60 height=18 rx=4 fill=#76d75a stroke=#263a27 stroke-width=3></rect>';h+='<circle cx=82 cy='+S.y+' r=13 fill=#f5c84c stroke=#15191c stroke-width=3></circle>';h+='<circle cx=87 cy='+(S.y-4)+' r=4 fill=#fff4c7></circle>';h+='<circle cx=88 cy='+(S.y-4)+' r=2 fill=#15191c></circle>';ui.html('world',h);ui.text('hud',String(S.score));ui.text('score',String(S.score))}function hint(t){ui.text('hint',t)}
function reset(){S.y=155;S.v=0;S.pipe=410;S.gap=150;S.score=0;S.over=false;S.running=false;hint('Klick / Touch im Spielfeld oder Flap. Leertaste / Pfeil hoch nach Fokus.');draw();ui.persist()}
function flap(){if(S.over)reset();S.running=true;S.v=-125;hint('Flieg durch die Lücken.');draw()}
function tick(e){if(!S.running||S.over)return;var dt=Math.min(e.dt,100)/1000;S.v=Math.min(200,S.v+350*dt);S.y+=S.v*dt;S.pipe-=72*dt;if(S.pipe+52<0){S.pipe=480;S.gap=[150,185,105,165][S.score%4]}if(S.pipe+52>=70&&S.pipe+52<70+72*dt)S.score++;if(S.y-12<=0||S.y+12>=270||(S.pipe<94&&S.pipe+52>70&&(S.y-12<S.gap-55||S.y+12>S.gap+55))){S.over=true;S.running=false;hint('Game over — '+S.score+' Punkt(e). Flap startet neu.');ui.persist()}draw()}
ui.on('flap','click',flap);ui.on('scene','click',flap);ui.on('scene','keydown',e=>{if(!e.repeat&&(e.code==='Space'||e.code==='ArrowUp'))flap()});ui.on('wait','click',()=>{if(S.over)return;S.running=!S.running;hint(S.running?'Weiter geht’s.':'Pause — Flap zum Weiterspielen.');ui.persist()});ui.on('restart','click',reset);S.running=false;ui.every(50,tick);hint('Klick / Touch im Spielfeld oder Flap. Leertaste / Pfeil hoch nach Fokus.');draw();
